  "python": "def pilot_policy(trace):
    if not trace:
        raise PolicyViolation("Trace is empty")
    action, label = trace[-1]
    action_name = action.name
    arguments = json.loads(action.arguments)
    categories = label.subset
    policy = {
        "slot:archive": ["UNVERIFIED"],
        "slot:counsel": ["UNVERIFIED"],
        "slot:public": ["PERSONAL", "EMBARGOED", "LICENSED"],
        "slot:syndicate": ["PERSONAL", "EMBARGOED"],
        "slot:wire": ["PERSONAL", "LICENSED"]
    }
    if action_name == "research/collect_material":
        return None
    elif action_name == "editor/edit_draft":
        return None
    elif action_name == "publisher/review_release":
        return None
    elif action_name == "legal/publish" or action_name == "editorial/publish":
        if action_name.startswith("legal"):
            team = "legal"
        else:
            team = "editorial"
        audience = arguments.get("audience")
        record = arguments.get("record")
        if team == "editorial":
            if audience == "staff":
                primary_slot = "slot:newsroom"
            elif audience == "partner":
                primary_slot = "slot:syndicate"
            elif audience == "release":
                primary_slot = "slot:public"
            else:
                raise PolicyViolation("Invalid audience for editorial")
        elif team == "legal":
            if audience == "staff":
                primary_slot = "slot:newsroom"
            elif audience == "partner":
                primary_slot = "slot:counsel"
            elif audience == "release":
                primary_slot = "slot:wire"
            else:
                raise PolicyViolation("Invalid audience for legal")
        else:
            raise PolicyViolation("Unknown team")
        additional_slots = []
        if record == "archive":
            additional_slots.append("slot:archive")
        elif record == "partner":
            if team == "editorial":
                additional_slots.append("slot:syndicate")
            else:
                additional_slots.append("slot:counsel")
        elif record == "public":
            additional_slots.append("slot:public")
        elif record == "none":
            pass
        else:
            raise PolicyViolation("Invalid record")
        all_slots = [primary_slot] + additional_slots
        for slot in all_slots:
            if slot in policy:
                allowed = set(policy[slot])
                if not categories.issubset(allowed):
                    raise PolicyViolation(f"Categories {categories} not allowed in {slot}")
        return None
    else:
        raise PolicyViolation("Unknown action")"
